img.Position = UDim2.fromScale(0.5, 0.5)   -- centered
img.Size = UDim2.fromScale(0.5, 0.5)       -- 50% x 50% = 1/4 of the screen
img.BackgroundTransparency = 1
img.ScaleType = Enum.ScaleType.Fit
img.Image = assetId
img.Parent = gui

-- Remove after 10 seconds
task.delay(SHOW_TIME, function()
    gui:Destroy()
    pcall(delfile, FILE_NAME)
end)

